      g.font = `400 19px ${FONT}`; g.fillStyle = '#6f828c'; g.textAlign = 'right'; g.fillText(`${sched.length} patients · fictional · not for clinical use`, w - 40, 50); g.textAlign = 'left'; g.fillStyle = '#ff5a3c'; g.fillRect(40, 64, 80, 3);
      const cols = 4, rows = Math.ceil(order.length / cols), cw = (w - 80) / cols, rh = (h - 92) / rows;
